MERGE dbo.CatalogDomain AS t
USING d ON t.DomainKey = d.DomainKey
WHEN NOT MATCHED THEN
    INSERT (DomainKey, Scope, LabelJson, IsSystem, IsActive)
    VALUES (d.DomainKey, d.Scope, N'{"es":"'+d.Es+'","en":"'+d.En+'"}', 1, 1);
GO

