MERGE dbo.StatusCode AS t
USING #S AS s ON t.Entity = s.Entity AND t.InternalCode = s.Code
WHEN NOT MATCHED THEN
    INSERT (Entity, InternalCode, LabelJson, ColorHex, SortOrder, StageKindLookupId, IsInitial, IsActive)
    VALUES (s.Entity, s.Code, N'{"es":"'+s.Es+'","en":"'+s.En+'"}', s.Color, s.Srt, s.Stage, s.IsInitial, 1);

-- Lote 2: reorden idempotente de PortalUserStatus en BD ya sembradas (el MERGE solo inserta; SUSPENDED entra por el MERGE)
UPDATE dbo.StatusCode
SET IsInitial = CASE InternalCode WHEN 'INVITED' THEN 1 ELSE 0 END,
    SortOrder = CASE InternalCode WHEN 'INVITED' THEN 1 WHEN 'ACTIVE' THEN 2 WHEN 'SUSPENDED' THEN 3 WHEN 'DISABLED' THEN 4 ELSE SortOrder END
WHERE Entity = 'PortalUserStatus' AND InternalCode IN ('INVITED','ACTIVE','SUSPENDED','DISABLED');

-- Lote 6 (D16): en BD ya sembradas, RESERVED y SHIPPED de SerialStatus pasan a LATERAL (AVAILABLE → SHIPPED → AVAILABLE es legal
-- y queda con historial: reversas de recolección y devoluciones). Idempotente.
UPDATE dbo.StatusCode SET StageKindLookupId = @LAT
WHERE Entity = 'SerialStatus' AND InternalCode IN ('RESERVED','SHIPPED') AND StageKindLookupId <> @LAT;

-- Lote 13: en BD ya sembradas, RECEIVED y PUTAWAY del recibo toman etiqueta, orden y color nuevos (el MERGE solo inserta).
-- Idempotente.
UPDATE dbo.StatusCode
SET LabelJson = CASE InternalCode WHEN 'RECEIVED' THEN N'{"es":"Completado","en":"Completed"}' ELSE N'{"es":"Acomodado","en":"Put away"}' END,
    SortOrder = CASE InternalCode WHEN 'RECEIVED' THEN 4 ELSE 6 END,
    ColorHex  = CASE InternalCode WHEN 'RECEIVED' THEN '#10B981' ELSE '#059669' END
WHERE Entity = 'ReceiptStatus' AND InternalCode IN ('RECEIVED','PUTAWAY');

-- Lote 13: los recibos que quedaron en OPEN pasan a RECEIVING (con líneas) o EXPECTED (sin líneas), con historial; después
-- OPEN se retira (IsActive = 0, IsInitial = 0) para que EXPECTED sea la única etapa inicial. Idempotente: sin recibos OPEN
-- no inserta nada y el UPDATE de OPEN vuelve a dejar los mismos valores.
DECLARE @RcOpen INT = (SELECT StatusCodeId FROM dbo.StatusCode WHERE Entity = 'ReceiptStatus' AND InternalCode = 'OPEN');
IF @RcOpen IS NOT NULL
BEGIN
    DECLARE @RcExpected  INT = (SELECT StatusCodeId FROM dbo.StatusCode WHERE Entity = 'ReceiptStatus' AND InternalCode = 'EXPECTED');
    DECLARE @RcReceiving INT = (SELECT StatusCodeId FROM dbo.StatusCode WHERE Entity = 'ReceiptStatus' AND InternalCode = 'RECEIVING');
    DECLARE @RcEntity    INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'EntityType' AND InternalCode = 'RECEIPT');

    INSERT INTO dbo.EntityStatusHistory (TenantId, EntityTypeLookupId, EntityId, FromStatusCodeId, ToStatusCodeId, Comment, ChangedAtUtc, ChangedBy)
    SELECT r.TenantId, @RcEntity, r.ReceiptHeaderId, @RcOpen,
           CASE WHEN EXISTS (SELECT 1 FROM dbo.ReceiptLine l WHERE l.ReceiptHeaderId = r.ReceiptHeaderId) THEN @RcReceiving ELSE @RcExpected END,
           N'Lote 13: nuevo ciclo de estatus del recibo.', SYSUTCDATETIME(), NULL
    FROM dbo.ReceiptHeader r
    WHERE r.StatusCodeId = @RcOpen;

    UPDATE r
    SET StatusCodeId = CASE WHEN EXISTS (SELECT 1 FROM dbo.ReceiptLine l WHERE l.ReceiptHeaderId = r.ReceiptHeaderId) THEN @RcReceiving ELSE @RcExpected END
    FROM dbo.ReceiptHeader r
    WHERE r.StatusCodeId = @RcOpen;

    UPDATE dbo.StatusCode SET IsActive = 0, IsInitial = 0 WHERE StatusCodeId = @RcOpen;
END

-- Lote 14 (D7): en BD ya sembradas, OPEN y RECONCILED del conteo toman las etiquetas nuevas ('Pendiente' y 'Concordancia'; el
-- MERGE solo inserta). Idempotente.
UPDATE dbo.StatusCode
SET LabelJson = CASE InternalCode WHEN 'OPEN' THEN N'{"es":"Pendiente","en":"Pending"}' ELSE N'{"es":"Concordancia","en":"Matched"}' END
WHERE Entity = 'CycleCountStatus' AND InternalCode IN ('OPEN','RECONCILED')
  AND LabelJson <> CASE InternalCode WHEN 'OPEN' THEN N'{"es":"Pendiente","en":"Pending"}' ELSE N'{"es":"Concordancia","en":"Matched"}' END;

-- Lote 14 (D7): los conteos ya reconciliados con alguna línea que asentó un ajuste (AdjustmentTxnId) pasan a
-- RECONCILED_VARIANCE 'Diferencia', con historial. Idempotente: sin conteos RECONCILED con ajuste no inserta nada.
DECLARE @CcReconciled INT = (SELECT StatusCodeId FROM dbo.StatusCode WHERE Entity = 'CycleCountStatus' AND InternalCode = 'RECONCILED');
DECLARE @CcVariance   INT = (SELECT StatusCodeId FROM dbo.StatusCode WHERE Entity = 'CycleCountStatus' AND InternalCode = 'RECONCILED_VARIANCE');
DECLARE @CcEntity     INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'EntityType' AND InternalCode = 'CYCLE_COUNT');
IF @CcReconciled IS NOT NULL AND @CcVariance IS NOT NULL AND @CcEntity IS NOT NULL
BEGIN
    INSERT INTO dbo.EntityStatusHistory (TenantId, EntityTypeLookupId, EntityId, FromStatusCodeId, ToStatusCodeId, Comment, ChangedAtUtc, ChangedBy)
    SELECT c.TenantId, @CcEntity, c.CycleCountId, @CcReconciled, @CcVariance, N'Lote 14: conteo con diferencia.', SYSUTCDATETIME(), NULL
    FROM dbo.CycleCount c
    WHERE c.StatusCodeId = @CcReconciled
      AND EXISTS (SELECT 1 FROM dbo.CycleCountLine l WHERE l.CycleCountId = c.CycleCountId AND l.AdjustmentTxnId IS NOT NULL);

    UPDATE c SET StatusCodeId = @CcVariance
    FROM dbo.CycleCount c
    WHERE c.StatusCodeId = @CcReconciled
      AND EXISTS (SELECT 1 FROM dbo.CycleCountLine l WHERE l.CycleCountId = c.CycleCountId AND l.AdjustmentTxnId IS NOT NULL);
END

-- Lote 14 (D2): los conteos anteriores al lote se crearon por selección: origen MANUAL. Idempotente.
DECLARE @CcManual INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'CycleCountOrigin' AND InternalCode = 'MANUAL');
IF @CcManual IS NOT NULL
    UPDATE dbo.CycleCount SET OriginLookupId = @CcManual WHERE OriginLookupId IS NULL;

-- Lote 14 (D7): el indicador de sistema 'Conteos con diferencia' de las compañías ya creadas pasa a contar el estatus
-- RECONCILED_VARIANCE (SystemAnalyticsSeeder.ReconciledCountsWithVarianceFilter). Solo se reemplaza el filtro original exacto
-- (no se pisa uno personalizado). Idempotente.
UPDATE dbo.IndicatorDefinition
SET FilterJson = N'{"and":[{"field":"StatusCode","op":"eq","value":"RECONCILED_VARIANCE"}]}', UpdatedAtUtc = SYSUTCDATETIME()
WHERE IsSystem = 1 AND Name = N'Conteos con diferencia'
  AND FilterJson = N'{"and":[{"field":"StatusCode","op":"eq","value":"RECONCILED"},{"field":"HasVariance","op":"isTrue"}]}';
GO

/* -------------------------------------------------------------------------
   Lote 15 — Pulso del día: gráficos de almacén de la compañía y 'Descuadres pendientes' en las compañías YA CREADAS
   (incluidas las migradas: Advance Depot y Advance Solutions). Mismo criterio que SystemAnalyticsSeeder (que siembra las
   compañías nuevas y la demo). Idempotente; al ser SQL no deja AuditLog (como el bloque 5b).
   - D9/D10/D12/D14: "Valor de inventario por categoría" (barras de sistema) pasa a DONA y "Movimientos de inventario por tipo"
     (suma CON signo de Quantity) pasa a unidades positivas (campo Units); ambos dejan de ser de sistema y quedan DE LA
     COMPAÑÍA (IsSystem = 0, sin dueño: los edita o borra quien tenga analytics.manage) con su SeedKey. Solo se convierte la
     fila de sistema que sigue exactamente como se sembró, y solo si la compañía no tiene ya esa SeedKey. El rango que la
     compañía haya puesto se conserva.
   - D13: primera fila de "Tus gráficos" (orden 1 y 2) solo si el orden sigue en el de fábrica (90 y 96) y la compañía no
     organizó sus gráficos (Organizar guarda índice × 10 desde 0: algún gráfico activo con orden 0).
   - D14: si se borran NO vuelven: la fila borrada (IsActive = 0) conserva su SeedKey y el nombre, y ambos bloquean el INSERT.
   - Las compañías sin esos gráficos (anteriores al Lote 6) los reciben ya como de la compañía.
   - D16: indicador de sistema 'Descuadres pendientes' (fuente INVENTORY_DISCREPANCY, estatus OPEN, rango ALL), apagado en el
     Pulso; por nombre (uno de sistema no se renombra ni se borra).
   Solo compañías con contenido de análisis sembrado (algún gráfico o indicador de sistema).
   ------------------------------------------------------------------------- */
DECLARE @L15Bar    INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'ReportChartType' AND InternalCode = 'BAR');
DECLARE @L15Donut  INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'ReportChartType' AND InternalCode = 'DONUT');
DECLARE @L15Sum    INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'AggregateFn' AND InternalCode = 'SUM');
DECLARE @L15Count  INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'AggregateFn' AND InternalCode = 'COUNT');
DECLARE @L15Wh     INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'BusinessModule' AND InternalCode = 'WAREHOUSE');
DECLARE @L15Tenant INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'ReportVisibility' AND InternalCode = 'TENANT');
DECLARE @L15Last7  INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'DateRangeMode' AND InternalCode = 'LAST7');
DECLARE @L15All    INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'DateRangeMode' AND InternalCode = 'ALL');
IF @L15Bar IS NOT NULL AND @L15Donut IS NOT NULL AND @L15Sum IS NOT NULL AND @L15Count IS NOT NULL AND @L15Wh IS NOT NULL
   AND @L15Tenant IS NOT NULL AND @L15Last7 IS NOT NULL AND @L15All IS NOT NULL
BEGIN
    -- 1) Conversión de "Valor de inventario por categoría" (barras de sistema → dona de la compañía).
    UPDATE c
    SET IsSystem = 0, OwnerUserId = NULL, SeedKey = N'INVENTORY_VALUE', ChartTypeLookupId = @L15Donut,
        SortOrder = CASE WHEN c.SortOrder = 90
                          AND NOT EXISTS (SELECT 1 FROM dbo.ChartDefinition o WHERE o.TenantId = c.TenantId AND o.IsActive = 1 AND o.SortOrder = 0)
                         THEN 1 ELSE c.SortOrder END,
        UpdatedAtUtc = SYSUTCDATETIME()
    FROM dbo.ChartDefinition c
    WHERE c.IsSystem = 1 AND c.SeedKey IS NULL AND c.Name = N'Valor de inventario por categoría'
      AND c.DataSourceKey = 'STOCK_BALANCE' AND c.GroupByField = 'Category' AND c.FieldKey = 'CostValue' AND c.ChartTypeLookupId = @L15Bar
      AND NOT EXISTS (SELECT 1 FROM dbo.ChartDefinition k WHERE k.TenantId = c.TenantId AND k.SeedKey = N'INVENTORY_VALUE');

    -- 2) Conversión de "Movimientos de inventario por tipo" (suma con signo → unidades positivas, de la compañía).
    UPDATE c
    SET IsSystem = 0, OwnerUserId = NULL, SeedKey = N'MOVEMENTS_BY_TYPE', FieldKey = 'Units',
        DescriptionJson = N'{"es":"Unidades movidas en el período por tipo de movimiento (siempre en positivo)","en":"Units moved in the period by movement type (always positive)"}',
        SortOrder = CASE WHEN c.SortOrder = 96
                          AND NOT EXISTS (SELECT 1 FROM dbo.ChartDefinition o WHERE o.TenantId = c.TenantId AND o.IsActive = 1 AND o.SortOrder = 0)
                         THEN 2 ELSE c.SortOrder END,
        UpdatedAtUtc = SYSUTCDATETIME()
    FROM dbo.ChartDefinition c
    WHERE c.IsSystem = 1 AND c.SeedKey IS NULL AND c.Name = N'Movimientos de inventario por tipo'
      AND c.DataSourceKey = 'INVENTORY_TRANSACTION' AND c.GroupByField = 'TxnType' AND c.FieldKey = 'Quantity' AND c.ChartTypeLookupId = @L15Bar
      AND NOT EXISTS (SELECT 1 FROM dbo.ChartDefinition k WHERE k.TenantId = c.TenantId AND k.SeedKey = N'MOVEMENTS_BY_TYPE');

    -- 3) Compañías que no los tienen (ni la SeedKey ni el nombre, activos o borrados): se crean ya como de la compañía.
    INSERT INTO dbo.ChartDefinition (TenantId, Name, DescriptionJson, DataSourceKey, GroupByField, FieldKey, AggregateFnLookupId, ChartTypeLookupId,
        FilterJson, BusinessModuleLookupId, IsMoney, IsSystem, OwnerUserId, VisibilityLookupId, DateRangeModeLookupId, ShowInPulse, SortOrder, IsActive, SeedKey)
    SELECT t.TenantId, N'Valor de inventario por categoría', N'{"es":"Existencia valorada a costo por categoría","en":"Stock cost value by category"}',
        'STOCK_BALANCE', 'Category', 'CostValue', @L15Sum, @L15Donut, NULL, @L15Wh, 1, 0, NULL, @L15Tenant, NULL, 1,
        CASE WHEN EXISTS (SELECT 1 FROM dbo.ChartDefinition o WHERE o.TenantId = t.TenantId AND o.IsActive = 1 AND o.SortOrder = 0) THEN 90 ELSE 1 END,
        1, N'INVENTORY_VALUE'
    FROM dbo.Tenant t
    WHERE EXISTS (SELECT 1 FROM dbo.ChartDefinition x WHERE x.TenantId = t.TenantId AND x.IsSystem = 1)
      AND NOT EXISTS (SELECT 1 FROM dbo.ChartDefinition k WHERE k.TenantId = t.TenantId
                      AND (k.SeedKey = N'INVENTORY_VALUE' OR k.Name = N'Valor de inventario por categoría'));

    INSERT INTO dbo.ChartDefinition (TenantId, Name, DescriptionJson, DataSourceKey, GroupByField, FieldKey, AggregateFnLookupId, ChartTypeLookupId,
        FilterJson, BusinessModuleLookupId, IsMoney, IsSystem, OwnerUserId, VisibilityLookupId, DateRangeModeLookupId, ShowInPulse, SortOrder, IsActive, SeedKey)
    SELECT t.TenantId, N'Movimientos de inventario por tipo',
        N'{"es":"Unidades movidas en el período por tipo de movimiento (siempre en positivo)","en":"Units moved in the period by movement type (always positive)"}',
        'INVENTORY_TRANSACTION', 'TxnType', 'Units', @L15Sum, @L15Bar, NULL, @L15Wh, 0, 0, NULL, @L15Tenant, @L15Last7, 1,
        CASE WHEN EXISTS (SELECT 1 FROM dbo.ChartDefinition o WHERE o.TenantId = t.TenantId AND o.IsActive = 1 AND o.SortOrder = 0) THEN 96 ELSE 2 END,
        1, N'MOVEMENTS_BY_TYPE'
    FROM dbo.Tenant t
    WHERE EXISTS (SELECT 1 FROM dbo.ChartDefinition x WHERE x.TenantId = t.TenantId AND x.IsSystem = 1)
      AND NOT EXISTS (SELECT 1 FROM dbo.ChartDefinition k WHERE k.TenantId = t.TenantId
                      AND (k.SeedKey = N'MOVEMENTS_BY_TYPE' OR k.Name = N'Movimientos de inventario por tipo'));

    -- 4) D16: 'Descuadres pendientes' (sistema, apagado en el Pulso, orden 99, módulo Almacén).
    INSERT INTO dbo.IndicatorDefinition (TenantId, Name, DescriptionJson, DataSourceKey, FieldKey, AggregateFnLookupId, FilterJson,
        BusinessModuleLookupId, IsMoney, IsSystem, OwnerUserId, VisibilityLookupId, DateRangeModeLookupId, ShowInPulse, SortOrder, IsActive)
    SELECT t.TenantId, N'Descuadres pendientes',
        N'{"es":"Descuadres entre el Kárdex y el saldo pendientes de revisar","en":"Ledger vs. balance discrepancies pending review"}',
        'INVENTORY_DISCREPANCY', NULL, @L15Count, N'{"and":[{"field":"StatusCode","op":"eq","value":"OPEN"}]}',
        @L15Wh, 0, 1, NULL, @L15Tenant, @L15All, 0, 99, 1
    FROM dbo.Tenant t
    WHERE EXISTS (SELECT 1 FROM dbo.IndicatorDefinition x WHERE x.TenantId = t.TenantId AND x.IsSystem = 1)
      AND NOT EXISTS (SELECT 1 FROM dbo.IndicatorDefinition i WHERE i.TenantId = t.TenantId AND i.Name = N'Descuadres pendientes');
END
GO

/* -------------------------------------------------------------------------
   Lote 16 — Recibo directo a posición: los almacenes y los recibos que no tienen modo de recepción quedan "Con acomodo"
   (PUTAWAY), el comportamiento de siempre (D2: los recibos conservan el modo con que se abrieron; D8: Depot y la demo con
   acomodo). El modo de Advance Solutions (DIRECT) sale de la configuración de migración, no de aquí. Idempotente: solo
   toca filas con el modo NULL.
   ------------------------------------------------------------------------- */
DECLARE @L16Putaway INT = (SELECT LookupCodeId FROM dbo.LookupCode WHERE Entity = 'ReceivingMode' AND InternalCode = 'PUTAWAY');
IF @L16Putaway IS NOT NULL
BEGIN
    UPDATE dbo.Warehouse SET ReceivingModeLookupId = @L16Putaway WHERE ReceivingModeLookupId IS NULL;
    UPDATE dbo.ReceiptHeader SET ReceivingModeLookupId = @L16Putaway WHERE ReceivingModeLookupId IS NULL;
END
GO

/* -------------------------------------------------------------------------
   3B) STATUS CAPABILITY por defecto (TenantId NULL) — Lote 2
       EDIT_CONTRACT no permitido en contratos EXPIRED/CANCELLED (el tenant lo
       puede cambiar desde /status/capabilities/CONTRACT).
   ------------------------------------------------------------------------- */
MERGE dbo.StatusCapability AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, s.StatusCodeId, c.LookupCodeId AS CapabilityLookupId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode s
    CROSS JOIN dbo.LookupCode c
    WHERE et.Entity='EntityType' AND et.InternalCode='CONTRACT'
      AND s.Entity='ContractStatus' AND s.InternalCode IN ('EXPIRED','CANCELLED')
      AND c.Entity='Capability' AND c.InternalCode='EDIT_CONTRACT'
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.StatusCodeId = s.StatusCodeId AND t.CapabilityLookupId = s.CapabilityLookupId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, StatusCodeId, CapabilityLookupId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.StatusCodeId, s.CapabilityLookupId, 0);
GO

/* -------------------------------------------------------------------------
   3C) STATUS CAPABILITY por defecto (TenantId NULL) — Lote 3, TRANSPORT_ORDER
       EDIT_CARGO solo en DRAFT ('editable solo en Entrada', L1063/L1088); REPRICE solo en CONFIRMED;
       CANCEL apagado en DELIVERED/CANCELLED; ASSIGN_TRIP apagado en DRAFT y terminales.
       El tenant lo cambia desde /status/capabilities/TRANSPORT_ORDER.
   ------------------------------------------------------------------------- */
MERGE dbo.StatusCapability AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, s.StatusCodeId, c.LookupCodeId AS CapabilityLookupId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode s
    CROSS JOIN dbo.LookupCode c
    WHERE et.Entity='EntityType' AND et.InternalCode='TRANSPORT_ORDER'
      AND s.Entity='OrderStatus' AND c.Entity='Capability'
      AND (
           (c.InternalCode='EDIT_CARGO'  AND s.InternalCode IN ('CONFIRMED','PICKUP','INBOUND','PLANNED','IN_TRANSIT','ARRIVED','DELIVERED','ON_HOLD','PARTIAL','FAILED','CANCELLED'))
        OR (c.InternalCode='REPRICE'     AND s.InternalCode IN ('DRAFT','PICKUP','INBOUND','PLANNED','IN_TRANSIT','ARRIVED','DELIVERED','ON_HOLD','PARTIAL','FAILED','CANCELLED'))
        OR (c.InternalCode='CANCEL'      AND s.InternalCode IN ('DELIVERED','CANCELLED'))
        OR (c.InternalCode='ASSIGN_TRIP' AND s.InternalCode IN ('DRAFT','DELIVERED','CANCELLED'))
      )
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.StatusCodeId = s.StatusCodeId AND t.CapabilityLookupId = s.CapabilityLookupId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, StatusCodeId, CapabilityLookupId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.StatusCodeId, s.CapabilityLookupId, 0);
GO

/* -------------------------------------------------------------------------
   3D) STATUS CAPABILITY por defecto (TenantId NULL) — Lote 4, WORK_ORDER
       EDIT_WORK_ORDER no permitido en órdenes de trabajo CLOSED/CANCELLED (el
       tenant lo puede cambiar desde /status/capabilities/WORK_ORDER).
   ------------------------------------------------------------------------- */
MERGE dbo.StatusCapability AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, s.StatusCodeId, c.LookupCodeId AS CapabilityLookupId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode s
    CROSS JOIN dbo.LookupCode c
    WHERE et.Entity='EntityType' AND et.InternalCode='WORK_ORDER'
      AND s.Entity='WorkOrderStatus' AND s.InternalCode IN ('CLOSED','CANCELLED')
      AND c.Entity='Capability' AND c.InternalCode='EDIT_WORK_ORDER'
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.StatusCodeId = s.StatusCodeId AND t.CapabilityLookupId = s.CapabilityLookupId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, StatusCodeId, CapabilityLookupId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.StatusCodeId, s.CapabilityLookupId, 0);
GO

/* -------------------------------------------------------------------------
   3E) STATUS CAPABILITY por defecto (TenantId NULL) — Lote 5, TRIP
       EDIT_TRIP (cabecera: chofer, vehículo, hora de salida) no permitido en
       rutas DISPATCHED/IN_PROGRESS/COMPLETED/CANCELLED. El tenant la puede
       habilitar en DISPATCHED/IN_PROGRESS desde /status/capabilities/TRIP
       (la fecha, la zona y el contenido de una ruta despachada nunca cambian).
   ------------------------------------------------------------------------- */
MERGE dbo.StatusCapability AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, s.StatusCodeId, c.LookupCodeId AS CapabilityLookupId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode s
    CROSS JOIN dbo.LookupCode c
    WHERE et.Entity='EntityType' AND et.InternalCode='TRIP'
      AND s.Entity='TripStatus' AND s.InternalCode IN ('DISPATCHED','IN_PROGRESS','COMPLETED','CANCELLED')
      AND c.Entity='Capability' AND c.InternalCode='EDIT_TRIP'
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.StatusCodeId = s.StatusCodeId AND t.CapabilityLookupId = s.CapabilityLookupId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, StatusCodeId, CapabilityLookupId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.StatusCodeId, s.CapabilityLookupId, 0);
GO

/* -------------------------------------------------------------------------
   3F) STATUS LATERAL ENTRY por defecto (TenantId NULL) — Lote 5
       TRIP: CANCELLED ('Eliminar ruta') solo desde DRAFT y PLANNED (una ruta
       despachada no se elimina; TripStatusEffect lo vuelve a exigir).
       ROUTE: ARCHIVED solo desde DRAFT y OPTIMIZED (la versión ACTIVE está
       congelada). El tenant lo cambia desde /status/lateral-entries/{TRIP|ROUTE}.
   ------------------------------------------------------------------------- */
MERGE dbo.StatusLateralEntry AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, lat.StatusCodeId AS LateralStatusCodeId, frm.StatusCodeId AS FromStatusCodeId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode lat
    CROSS JOIN dbo.StatusCode frm
    WHERE et.Entity='EntityType'
      AND (
           (et.InternalCode='TRIP'  AND lat.Entity='TripStatus'  AND lat.InternalCode='CANCELLED'
                                    AND frm.Entity='TripStatus'  AND frm.InternalCode IN ('DRAFT','PLANNED'))
        OR (et.InternalCode='ROUTE' AND lat.Entity='RouteStatus' AND lat.InternalCode='ARCHIVED'
                                    AND frm.Entity='RouteStatus' AND frm.InternalCode IN ('DRAFT','OPTIMIZED'))
      )
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.LateralStatusCodeId = s.LateralStatusCodeId AND t.FromStatusCodeId = s.FromStatusCodeId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, LateralStatusCodeId, FromStatusCodeId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.LateralStatusCodeId, s.FromStatusCodeId, 1);
GO

/* -------------------------------------------------------------------------
   3G) STATUS LATERAL ENTRY por defecto (TenantId NULL) — Lote 6
       PICK_BATCH: CANCELLED ('Eliminar recolección') desde COLLECTED y PACKED.
       WAREHOUSE_TASK: CANCELLED desde PENDING e IN_PROGRESS.
       DOCK_APPOINTMENT: NO_SHOW y CANCELLED desde SCHEDULED.
       CROSSDOCK_ALLOCATION: CANCELLED desde PLANNED.
       ASN: CANCELLED desde EXPECTED.
       RECEIPT (Lote 13): DISCREPANCY desde RECEIVING; RECEIVED_VARIANCE desde RECEIVING, DISCREPANCY y EXPECTED;
       PUTAWAY desde RECEIVED_VARIANCE (desde RECEIVED es la siguiente etapa y no necesita regla).
       CYCLE_COUNT (Lote 14): RECONCILED_VARIANCE desde OPEN y COUNTED.
       PURCHASE_ORDER: SIN regla a propósito (D47). StatusService permite un lateral o terminal sin reglas desde cualquier
       etapa, así que CANCELLED se permite desde DRAFT, SENT y PARTIAL (RECEIVED es terminal y no admite más transiciones);
       el servicio exige además que no haya un recibo OPEN y deja el comentario en el historial.
       El tenant lo cambia desde /status/lateral-entries/{entidad}.
   ------------------------------------------------------------------------- */
MERGE dbo.StatusLateralEntry AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, lat.StatusCodeId AS LateralStatusCodeId, frm.StatusCodeId AS FromStatusCodeId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode lat
    CROSS JOIN dbo.StatusCode frm
    WHERE et.Entity='EntityType'
      AND (
           (et.InternalCode='PICK_BATCH'           AND lat.Entity='PickBatchStatus'     AND lat.InternalCode='CANCELLED'
                                                   AND frm.Entity='PickBatchStatus'     AND frm.InternalCode IN ('COLLECTED','PACKED'))
        OR (et.InternalCode='WAREHOUSE_TASK'       AND lat.Entity='WarehouseTaskStatus' AND lat.InternalCode='CANCELLED'
                                                   AND frm.Entity='WarehouseTaskStatus' AND frm.InternalCode IN ('PENDING','IN_PROGRESS'))
        OR (et.InternalCode='DOCK_APPOINTMENT'     AND lat.Entity='AppointmentStatus'   AND lat.InternalCode IN ('NO_SHOW','CANCELLED')
                                                   AND frm.Entity='AppointmentStatus'   AND frm.InternalCode='SCHEDULED')
        OR (et.InternalCode='CROSSDOCK_ALLOCATION' AND lat.Entity='AllocationStatus'    AND lat.InternalCode='CANCELLED'
                                                   AND frm.Entity='AllocationStatus'    AND frm.InternalCode='PLANNED')
        OR (et.InternalCode='ASN'                  AND lat.Entity='AsnStatus'           AND lat.InternalCode='CANCELLED'
                                                   AND frm.Entity='AsnStatus'           AND frm.InternalCode='EXPECTED')
        -- Lote 13 (RECEIPT): DISCREPANCY desde RECEIVING; RECEIVED_VARIANCE desde RECEIVING, DISCREPANCY y EXPECTED (este
        -- último solo se usa si la compañía apaga RECEIVING); PUTAWAY (terminal) desde RECEIVED_VARIANCE.
        OR (et.InternalCode='RECEIPT'              AND lat.Entity='ReceiptStatus'       AND lat.InternalCode='DISCREPANCY'
                                                   AND frm.Entity='ReceiptStatus'       AND frm.InternalCode='RECEIVING')
        OR (et.InternalCode='RECEIPT'              AND lat.Entity='ReceiptStatus'       AND lat.InternalCode='RECEIVED_VARIANCE'
                                                   AND frm.Entity='ReceiptStatus'       AND frm.InternalCode IN ('RECEIVING','DISCREPANCY','EXPECTED'))
        OR (et.InternalCode='RECEIPT'              AND lat.Entity='ReceiptStatus'       AND lat.InternalCode='PUTAWAY'
                                                   AND frm.Entity='ReceiptStatus'       AND frm.InternalCode='RECEIVED_VARIANCE')
        -- Lote 14 (CYCLE_COUNT, D7/D8): 'Diferencia' desde Contado (a ciegas) y desde Pendiente ("Confirmar conteo y ajustar"
        -- en un paso). 'Concordancia' no lleva regla: desde COUNTED es la siguiente etapa y desde OPEN, sin reglas, se permite.
        OR (et.InternalCode='CYCLE_COUNT'          AND lat.Entity='CycleCountStatus'    AND lat.InternalCode='RECONCILED_VARIANCE'
                                                   AND frm.Entity='CycleCountStatus'    AND frm.InternalCode IN ('OPEN','COUNTED'))
      )
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.LateralStatusCodeId = s.LateralStatusCodeId AND t.FromStatusCodeId = s.FromStatusCodeId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, LateralStatusCodeId, FromStatusCodeId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.LateralStatusCodeId, s.FromStatusCodeId, 1);
GO

/* -------------------------------------------------------------------------
   3H) STATUS CAPABILITY por defecto (TenantId NULL) — Lote 6, PURCHASE_ORDER
       EDIT_PURCHASE_ORDER (fechas, notas y líneas) no permitido en órdenes de compra
       SENT, PARTIAL, RECEIVED y CANCELLED (D46). El tenant la puede habilitar en
       SENT/PARTIAL desde /status/capabilities/PURCHASE_ORDER; aun así, las líneas
       con recepciones no se eliminan, no bajan de lo recibido y no cambian de costo.
   ------------------------------------------------------------------------- */
MERGE dbo.StatusCapability AS t
USING (
    SELECT et.LookupCodeId AS EntityTypeLookupId, s.StatusCodeId, c.LookupCodeId AS CapabilityLookupId
    FROM dbo.LookupCode et
    CROSS JOIN dbo.StatusCode s
    CROSS JOIN dbo.LookupCode c
    WHERE et.Entity='EntityType' AND et.InternalCode='PURCHASE_ORDER'
      AND s.Entity='PurchaseOrderStatus' AND s.InternalCode IN ('SENT','PARTIAL','RECEIVED','CANCELLED')
      AND c.Entity='Capability' AND c.InternalCode='EDIT_PURCHASE_ORDER'
) AS s
ON t.TenantId IS NULL AND t.EntityTypeLookupId = s.EntityTypeLookupId AND t.StatusCodeId = s.StatusCodeId AND t.CapabilityLookupId = s.CapabilityLookupId
WHEN NOT MATCHED THEN
    INSERT (TenantId, EntityTypeLookupId, StatusCodeId, CapabilityLookupId, IsAllowed)
    VALUES (NULL, s.EntityTypeLookupId, s.StatusCodeId, s.CapabilityLookupId, 0);
GO

